sp_widget.client_script:
function initializeEditableForm() {
  var submitBtn = document.getElementById('submitRefillBtn');
  var overlay = document.getElementById('successOverlay');
  var submissionSummary = document.getElementById('submissionSummary');

  if (!submitBtn || !overlay) return;

  function getFormData() {
    var patient = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Unknown';
    var medication = document.getElementById('medication') ? document.getElementById('medication').value : 'Unknown';
    var quantity = document.getElementById('quantity') ? document.getElementById('quantity').value : 'Unknown';

    return {
      patient: patient,
      medication: medication,
      quantity: quantity
    };
  }

  function showSuccess() {
    if (overlay.classList.contains('active')) return;

    // Get current form data to personalize success message
    var formData = getFormData();
    if (submissionSummary) {
      submissionSummary.innerHTML = 'Refill request for ' + formData.patient + ' has been submitted';
    }

    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';

    // Auto-close after 3 seconds
    setTimeout(function() {
      if (overlay.classList.contains('active')) {
        overlay.classList.remove('active');
        document.body.style.overflow = '';
      }
    }, 3200);
  }

  function handleSubmit() {
    // Validate required fields
    var patientName = document.getElementById('patientName');
    var medication = document.getElementById('medication');

    if (!patientName.value.trim()) {
      patientName.style.borderColor = '#dc2626';
      patientName.focus();
      return;
    }

    if (!medication.value.trim()) {
      medication.style.borderColor = '#dc2626';
      medication.focus();
      return;
    }

    // Reset border colors
    patientName.style.borderColor = '#d1d9e6';
    medication.style.borderColor = '#d1d9e6';

    // Show success animation
    showSuccess();

    // Optional: You can add logic here to save to ServiceNow
    console.log('Form Submitted:', getFormData());
  }

  // Remove any existing listeners and add new one
  var newSubmitBtn = submitBtn.cloneNode(true);
  submitBtn.parentNode.replaceChild(newSubmitBtn, submitBtn);

  newSubmitBtn.addEventListener('click', handleSubmit);

  // Clear red border on focus
  var inputs = document.querySelectorAll('.editable-input, .editable-textarea');
  inputs.forEach(function(input) {
    input.addEventListener('focus', function() {
      this.style.borderColor = '#d1d9e6';
    });
  });

  // Close overlay when clicking background
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) {
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    }
  });

  // Close with Escape key
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && overlay.classList.contains('active')) {
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    }
  });
}

// Initialize when widget loads
if (window.frameElement && window.frameElement.getAttribute('data-sn-widget')) {
  initializeEditableForm();
} else {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeEditableForm);
  } else {
    initializeEditableForm();
  }
}

sp_widget.css:
.trackmed-widget {
  max-width: 900px;
  width: 100%;
  background: #ffffff;
  border-radius: 2rem;
  box-shadow: 0 25px 45px -12px rgba(0, 0, 0, 0.25);
  overflow: hidden;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  margin: 0 auto;
}

.brand-header {
  background: #0b2b3b;
  padding: 1.2rem 2rem;
  color: white;
}

.brand-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-header h1 span {
  font-weight: 400;
  font-size: 0.9rem;
  background: #2c5a6e;
  padding: 0.2rem 0.7rem;
  border-radius: 40px;
}

.refill-badge {
  background: rgba(255, 255, 255, 0.15);
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.25rem 0.8rem;
  border-radius: 30px;
  margin-top: 0.5rem;
}

.request-content {
  padding: 1.8rem 2rem 1rem 2rem;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #edf2f7;
  padding: 1rem 0;
}

.info-label {
  font-weight: 600;
  color: #1e2a3e;
  font-size: 0.9rem;
  width: 30%;
}

.info-value {
  width: 70%;
  color: #0f2b3d;
  font-weight: 500;
}

.editable-input {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border: 1px solid #d1d9e6;
  border-radius: 0.5rem;
  font-size: 0.95rem;
  font-family: inherit;
  transition: all 0.2s ease;
  background: #fefefe;
}

.editable-input:focus {
  outline: none;
  border-color: #0f6b4f;
  box-shadow: 0 0 0 3px rgba(15, 107, 79, 0.1);
}

.editable-input:hover {
  border-color: #0f6b4f;
}

.status-select {
  cursor: pointer;
  background: white;
}

.editable-textarea {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border: 1px solid #d1d9e6;
  border-radius: 0.5rem;
  font-size: 0.95rem;
  font-family: inherit;
  resize: vertical;
  transition: all 0.2s ease;
}

.editable-textarea:focus {
  outline: none;
  border-color: #0f6b4f;
  box-shadow: 0 0 0 3px rgba(15, 107, 79, 0.1);
}

.notes-section {
  margin-top: 1rem;
  background: #f8fafc;
  padding: 1rem 1.2rem;
  border-radius: 1rem;
  border-left: 4px solid #2b7a62;
}

.notes-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  font-weight: 600;
  color: #2b6a54;
  margin-bottom: 0.5rem;
}

.notes-text {
  margin-top: 0.3rem;
}

.submit-action {
  margin: 1rem 2rem 2rem 2rem;
}

.submit-btn {
  width: 100%;
  background: #0f6b4f;
  border: none;
  padding: 1rem 0;
  font-size: 1.1rem;
  font-weight: 600;
  color: white;
  border-radius: 2rem;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 6px 14px rgba(15, 107, 79, 0.25);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
}

.submit-btn:hover {
  background: #0a5a42;
  transform: translateY(-2px);
  box-shadow: 0 12px 20px -8px rgba(15, 107, 79, 0.4);
}

.submit-btn:active {
  transform: translateY(1px);
}

/* Animation Overlay */
.animation-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2000;
  visibility: hidden;
  opacity: 0;
  transition: visibility 0s, opacity 0.25s ease;
}

.animation-overlay.active {
  visibility: visible;
  opacity: 1;
}

.success-card {
  background: white;
  border-radius: 3rem;
  padding: 2rem 2.5rem;
  text-align: center;
  max-width: 340px;
  width: 85%;
  box-shadow: 0 35px 60px rgba(0, 0, 0, 0.3);
  animation: floatIn 0.4s ease forwards;
}

@keyframes floatIn {
  0% {
    opacity: 0;
    transform: scale(0.85) translateY(20px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.tick-circle {
  width: 110px;
  height: 110px;
  margin: 0 auto 1.5rem auto;
}

.checkmark-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.checkmark-circle-bg {
  stroke: #0f6b4f;
  stroke-width: 3;
  fill: none;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: drawCircle 0.5s ease-out forwards;
}

.checkmark-tick {
  stroke: #0f6b4f;
  stroke-width: 5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 80;
  stroke-dashoffset: 80;
  animation: drawTick 0.4s ease-out 0.35s forwards;
}

@keyframes drawCircle {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes drawTick {
  to {
    stroke-dashoffset: 0;
  }
}

.submitted-text {
  font-size: 2rem;
  font-weight: 700;
  background: linear-gradient(135deg, #0f6b4f, #1e8f6b);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  margin: 0.5rem 0;
}

.extra-message {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: #5a6e7c;
}

@media (max-width: 600px) {
  .info-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .info-label, .info-value {
    width: 100%;
  }

  .request-content {
    padding: 1.5rem;
  }

  .submitted-text {
    font-size: 1.7rem;
  }
}

